mapper.sql:
WITH matrix_data AS ( SELECT t.stock_lot_id, l.location_code, l.customer_name, l.product_model, l.furnace_no, l.furnace_layer, l.package_weight, SUM(CASE WHEN t.biz_date < #{req.startDate} THEN t.quantity ELSE 0 END) AS opening_qty, SUM(CASE WHEN t.biz_date BETWEEN #{req.startDate} AND #{req.endDate} AND t.transaction_type IN ('OPENING','PRODUCTION_IN','INBOUND','ADJUST_IN') THEN t.quantity ELSE 0 END) AS inbound_qty, SUM(CASE WHEN t.biz_date BETWEEN #{req.startDate} AND #{req.endDate} AND t.transaction_type IN ('OUTBOUND','ADJUST_OUT') THEN t.quantity ELSE 0 END) AS outbound_qty, SUM(CASE WHEN t.biz_date BETWEEN #{req.startDate} AND #{req.endDate} AND t.transaction_type IN ('TRANSFER_IN','TRANSFER_OUT') THEN t.quantity ELSE 0 END) AS transfer_qty, SUM(CASE WHEN t.biz_date BETWEEN #{req.startDate} AND #{req.endDate} AND t.transaction_type = 'RETURN_IN' THEN t.quantity ELSE 0 END) AS return_qty, SUM(CASE WHEN t.biz_date <= #{req.endDate} THEN t.quantity ELSE 0 END) AS warehouse_qty FROM rd_stock_transaction t INNER JOIN rd_stock_lot l ON l.id = t.stock_lot_id AND l.tenant_id = #{tenantId} AND l.deleted = b'0' WHERE t.tenant_id = #{tenantId} AND t.deleted = b'0' AND t.stock_lot_id IS NOT NULL AND t.biz_date <= #{req.endDate}
AND l.location_code LIKE CONCAT('%', #{req.locationCode}, '%')
AND l.customer_name = #{req.customerName}
AND l.product_model = #{req.productModel}
AND l.furnace_no LIKE CONCAT('%', #{req.furnaceNo}, '%')
GROUP BY t.stock_lot_id, l.location_code, l.customer_name, l.product_model, l.furnace_no, l.furnace_layer, l.package_weight HAVING opening_qty != 0 OR inbound_qty != 0 OR outbound_qty != 0 OR transfer_qty != 0 OR return_qty != 0 )

mapper.select:
SELECT t.biz_date, SUM(CASE WHEN t.transaction_type IN ('OPENING','PRODUCTION_IN','INBOUND','ADJUST_IN') THEN t.quantity ELSE 0 END) AS inbound_qty, SUM(CASE WHEN t.transaction_type IN ('OUTBOUND','ADJUST_OUT') THEN t.quantity ELSE 0 END) AS outbound_qty, SUM(CASE WHEN t.transaction_type IN ('TRANSFER_IN','TRANSFER_OUT') THEN t.quantity ELSE 0 END) AS transfer_qty, SUM(CASE WHEN t.transaction_type = 'RETURN_IN' THEN t.quantity ELSE 0 END) AS return_qty FROM rd_stock_transaction t INNER JOIN rd_stock_lot l ON l.id = t.stock_lot_id AND l.tenant_id = #{tenantId} AND l.deleted = b'0' WHERE t.tenant_id = #{tenantId} AND t.deleted = b'0' AND t.biz_date BETWEEN #{req.startDate} AND #{req.endDate}
AND l.location_code LIKE CONCAT('%', #{req.locationCode}, '%')
AND l.customer_name = #{req.customerName}
AND l.product_model = #{req.productModel}
AND l.furnace_no LIKE CONCAT('%', #{req.furnaceNo}, '%')
GROUP BY t.biz_date ORDER BY t.biz_date
